INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Chiron', 'Mars', 'conjunction', 'Góc chiếu Conjunction giữa Chiron và Mars thể hiện sự tương tác năng lượng giữa hai hành tinh Chiron và Mars.', 'Trong cuộc sống hàng ngày, góc chiếu này tạo ra sự kết nối trực tiếp giữa năng lượng Chiron và biểu hiện của Mars.', 'Khả năng thích ứng cao, thấu hiểu tâm lý và phát huy sức mạnh tổng hợp từ Chiron và Mars.', 'Cần học cách cân bằng và hòa hợp nhu cầu của Chiron và Mars để tránh xung đột nội tâm.', '', '', ARRAY['Chiron', 'Mars', 'conjunction']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO NOTHING;
